#include <chrono>
#include <condition_variable>
#include <iostream>
#include <mutex>
int main() {
    std::mutex mutex;
    std::condition_variable changed;
    bool ready = false;
    changed.notify_one(); // This does not set ready or store a wakeup token.
    std::unique_lock lock(mutex);
    const bool notification_only = changed.wait_for(
        lock, std::chrono::milliseconds(0), [&] { return ready; });
    ready = true;
    const bool state_ready = changed.wait_for(
        lock, std::chrono::milliseconds(0), [&] { return ready; });
    std::cout << std::boolalpha << "notification only=" << notification_only << '\n';
    std::cout << "state ready=" << state_ready << '\n';
}

#include <array>
#include <condition_variable>
#include <iostream>
#include <mutex>
#include <thread>
int main() {
    std::mutex mutex;
    std::condition_variable changed;
    bool closed = false;
    std::array<int,2> finished{};
    const auto wait_for_close = [&](int id) {
        std::unique_lock lock(mutex);
        changed.wait(lock, [&] { return closed; });
        finished[id] = 1;
    };
    std::jthread a(wait_for_close,0), b(wait_for_close,1);
    { std::lock_guard lock(mutex); closed = true; }
    changed.notify_all();
    a.join(); b.join();
    std::cout << "finished=" << finished[0]+finished[1] << '\n';
}

